Here's a quick fix for your XSS vulnerability in the client-side JavaScript:

```javascript
// Use DOMPurify for better sanitization
function sanitizeUserInput(input) {
    // First, clean the input using a simple regex
    input = input.replace(/</g, '&lt;').replace(/>/g, '&gt;');

    // Then, use DOMPurify to thoroughly sanitize the input
    const DOMPurify = require('dompurify');
    const sanitizedInput = DOMPurify.sanitize(input, {
        ALLOWED_TAGS: ['b', 'i', 'u', 'p'], // Only allow certain tags (optional)
        ALLOWED_ATTR: ['href'],            // Only allow certain attributes (optional)
    });

    return sanitizedInput;
}
